using System.Text.Json;
using Vericairn.DocsTool;

namespace Vericairn.Cli.Tests;

/// <summary>
/// A release's documentation set: the references generated by the build tooling from the build they document, the shipped
/// command line's check refusing an incomplete set with every gap named, and the tooling's comparison of a set with its build.
/// </summary>
[Collection("cli")]
public class DocsTests
{
    private static readonly string[] Declared = ["README.md", "install.md", "operator-guide.md", "cli-reference.md", "api-reference.md", "record-reference.md", "record-format.md", "api.md", "software.md", "workbench.md", "mcp.md", "release-notes.md", "limitations-and-platforms.md"];

    private static readonly string[] Authored = ["README.md", "install.md", "operator-guide.md", "record-format.md", "api.md", "software.md", "workbench.md", "mcp.md", "release-notes.md", "limitations-and-platforms.md"];

    [Fact]
    public void TheBuildToolingWritesTheReferencesAndTheManifestFromThisBuild()
    {
        string output = CliHarness.TempDirectory("docs-generate");
        try
        {
            (int code, string text) = Tool(() => ReferenceSet.Generate(output, Declaration(output), json: true));
            Assert.True(code == 0, text);
            Assert.Equal(ReferenceSet.ReleaseVersion, JsonDocument.Parse(text).RootElement.GetProperty("version").GetString());
            foreach (string name in new[] { "cli-reference.md", "api-reference.md", "record-reference.md", "manifest.json" })
            {
                Assert.True(File.Exists(Path.Combine(output, name)), name);
            }

            using JsonDocument manifest = JsonDocument.Parse(File.ReadAllBytes(Path.Combine(output, "manifest.json")));
            List<string> commands = manifest.RootElement.GetProperty("commands").EnumerateArray().Select(c => c.GetString()!).ToList();
            Assert.Contains("docs check", commands);
            Assert.DoesNotContain("docs generate", commands);
            Assert.Contains("release providers", commands);
            Assert.Contains("records new", commands);
            Assert.Contains("estate upgrade", commands);
            Assert.Contains("GET /v1/providers", manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            Assert.Contains("work-order", manifest.RootElement.GetProperty("recordTypes").EnumerateArray().Select(t => t.GetString()));
            Assert.Equal(13, manifest.RootElement.GetProperty("documents").GetArrayLength());

            string cli = File.ReadAllText(Path.Combine(output, "cli-reference.md"));
            Assert.Contains("## `vericairn records`", cli, StringComparison.Ordinal);
            Assert.Contains("### `vericairn records new`", cli, StringComparison.Ordinal);
            Assert.Contains("`--by <by>`", cli, StringComparison.Ordinal);
            Assert.DoesNotContain(Directory.GetCurrentDirectory(), cli, StringComparison.Ordinal);
            Assert.Contains("## `POST /v1/records`", File.ReadAllText(Path.Combine(output, "api-reference.md")), StringComparison.Ordinal);
            Assert.Contains("## `acceptance`", File.ReadAllText(Path.Combine(output, "record-reference.md")), StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Fact]
    public void TheShippedCommandLineNoLongerGeneratesReferences()
    {
        CliHarness.Outcome outcome = CliHarness.Run("docs", "generate", "--out", Path.GetTempPath());
        Assert.NotEqual(0, outcome.Code);
    }

    [Fact]
    public void CheckAcceptsACompleteSetAndNamesEveryGapOfAnIncompleteOne()
    {
        string output = CliHarness.TempDirectory("docs-check");
        try
        {
            string declaration = Declaration(output);
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, declaration, json: false)).Code);
            foreach (string name in Authored)
            {
                File.WriteAllText(Path.Combine(output, name), $"# {name} for Vericairn {ReferenceSet.ReleaseVersion}\n\nAuthored.\n");
            }

            CliHarness.Outcome complete = CliHarness.Run("docs", "check", output, "--documents", declaration);
            Assert.True(complete.Code == 0, complete.Out + complete.Err);
            Assert.Contains("complete: 0 errors", complete.Out, StringComparison.Ordinal);

            File.Delete(Path.Combine(output, "install.md"));
            File.WriteAllText(Path.Combine(output, "README.md"), "# A set that forgot its version\n");
            string cliPath = Path.Combine(output, "cli-reference.md");
            File.WriteAllLines(cliPath, File.ReadAllLines(cliPath).Where(l => !l.Contains("`vericairn docs check`", StringComparison.Ordinal)));
            string recordPath = Path.Combine(output, "record-reference.md");
            File.WriteAllLines(recordPath, File.ReadAllLines(recordPath).Where(l => !l.Contains("## `acceptance`", StringComparison.Ordinal)));

            CliHarness.Outcome incomplete = CliHarness.Run("--json", "docs", "check", output);
            Assert.Equal(1, incomplete.Code);
            JsonElement findings = incomplete.Json;
            Assert.Equal(4, findings.GetProperty("errors").GetInt32());
            List<string> messages = findings.GetProperty("findings").EnumerateArray().Select(f => f.GetProperty("Location").GetString() + ": " + f.GetProperty("Message").GetString()).ToList();
            Assert.Contains(messages, m => m.StartsWith("install.md: Missing", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("README.md: Does not name the version", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("cli-reference.md: No heading for `vericairn docs check`", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("record-reference.md: No heading for `acceptance`", StringComparison.Ordinal));

            // A manifest that drops a document the product declares is refused against the declaration.
            string manifestPath = Path.Combine(output, "manifest.json");
            File.WriteAllText(manifestPath, File.ReadAllText(manifestPath).Replace("\"mcp.md\",", string.Empty, StringComparison.Ordinal));
            CliHarness.Outcome dropped = CliHarness.Run("docs", "check", output, "--documents", declaration);
            Assert.Contains("declares mcp.md", dropped.Out, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Fact]
    public void TheToolingRefusesAManifestThatDisagreesWithThisBuild()
    {
        string output = CliHarness.TempDirectory("docs-stale");
        try
        {
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, Declaration(output), json: false)).Code);
            Assert.Equal(0, Tool(() => ReferenceSet.CompareWithBuild(output, json: false)).Code);
            string manifestPath = Path.Combine(output, "manifest.json");
            string manifest = File.ReadAllText(manifestPath).Replace("\"docs check\"", "\"docs retired-verb\"", StringComparison.Ordinal);
            File.WriteAllText(manifestPath, manifest);

            (int code, string text) = Tool(() => ReferenceSet.CompareWithBuild(output, json: false));
            Assert.Equal(1, code);
            Assert.Contains("This build has the command vericairn docs check and the set does not", text, StringComparison.Ordinal);
            Assert.Contains("The set documents the command vericairn docs retired-verb, which this build does not have", text, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Theory]
    [InlineData("0.2.0")]
    [InlineData("0.3.0")]
    [InlineData("0.3.1")]
    public void TheReleasedSetsAreComplete(string version)
    {
        string? root = AppContext.BaseDirectory;
        while (root is not null && !File.Exists(Path.Combine(root, "Vericairn.slnx")))
        {
            root = Path.GetDirectoryName(root);
        }

        Assert.NotNull(root);
        string set = Path.Combine(root, "docs", "releases", version);
        CliHarness.Outcome outcome = CliHarness.Run("docs", "check", set);
        Assert.True(outcome.Code == 0, outcome.Out + outcome.Err);
        Assert.Contains("complete: 0 errors", outcome.Out, StringComparison.Ordinal);
    }

    private static string Declaration(string directory)
    {
        string path = Path.Combine(directory, "..", "documents-" + Path.GetFileName(directory) + ".json");
        File.WriteAllText(path, JsonSerializer.Serialize(Declared));
        return path;
    }

    private static (int Code, string Text) Tool(Func<int> action)
    {
        var output = new StringWriter { NewLine = "\n" };
        TextWriter previous = Console.Out;
        Console.SetOut(output);
        try
        {
            return (action(), output.ToString().Trim());
        }
        finally
        {
            Console.SetOut(previous);
        }
    }
}
